def sequence(spec):
 out='sequenceDiagram\n'
 for i,(label,_) in spec['actors'].items():out+='participant '+i+' as '+label+'\n'
 for a,b,label in spec['events']:out+=a+'->>'+b+': '+label.replace('<','#60;').replace('>','#62;')+'\n'
 return out
