  outputs.append({'figure_id':f'fig-{n:04d}','path':page.relative_to(root).as_posix(),'original':item['original'],'original_sha256':item['original_sha256'],'mermaid':(mmd/f'fig-{n:04d}.mmd').relative_to(root).as_posix(),'mermaid_sha256':hashlib.sha256(code.encode()).hexdigest(),'source_locator':occ['source_locator'],'word_file_page':wp,'flow':flow.relative_to(root).as_posix(),'flow_start':FLOW[n],'actors':spec['actors'],'events':spec['events'],'context_paragraphs':list(CONTEXT[n]),'limitations':notes,'issue_ids':issue,'visual_review':{'status':'not-run'}})
